package com.kigtts.next.sharing

import org.json.JSONObject

internal fun faceGallery(profile: JSONObject, assets: List<FaceAsset>, path: String): String {
    fun escape(value: String) = value.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;").replace("\"", "&quot;")
    val files = assets.joinToString("") { asset -> """<article><button class="photo" data-photo="${asset.id}"><img loading="lazy" src="${path}file/${asset.id}" alt="照片"></button><label><input type="checkbox" value="${asset.id}" checked>${if (asset.variant == "original") "原图" else "拍立得成片"}</label></article>""" }
    val name = escape(profile.optString("nickname", "KIGTTS 用户"))
    val bio = escape(profile.optString("bio"))
    val contacts = profile.optJSONArray("contacts")?.let { list -> (0 until minOf(8, list.length())).joinToString("") { index ->
        val link = list.getJSONObject(index); "<p>${escape(link.optString("label"))}：${escape(link.optString("value"))}</p>"
    } }.orEmpty()
    val clip = com.kigtts.next.identity.AvatarFrames.svgPath(profile.optString("avatarFrame", "circle"))
    val avatar = profile.optString("avatar").takeIf { it.matches(Regex("[A-Za-z0-9+/=]{1,65535}")) }?.let {
        """<svg width="64" height="64" viewBox="0 0 1 1" aria-label="头像"><defs><clipPath id="avatar-clip" clipPathUnits="objectBoundingBox"><path d="$clip"/></clipPath></defs><image href="data:image/jpeg;base64,$it" width="1" height="1" preserveAspectRatio="xMidYMid slice" clip-path="url(#avatar-clip)"/></svg>"""
    }.orEmpty()
    return """<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>领取照片</title>
<style>*,*:before{box-sizing:border-box}body{margin:0;background:#f1f7f6;color:#172e30;font:16px system-ui,sans-serif}header,main{max-width:960px;margin:auto;padding:24px}h1{font-size:32px;margin:8px 0}p{line-height:1.6}main{display:grid;grid-template-columns:repeat(auto-fill,minmax(150px,1fr));gap:12px;padding-bottom:120px}article{border-radius:24px;overflow:hidden;background:#dfedeb}.photo{display:block;width:100%;aspect-ratio:1;padding:0;border:0;background:#d0e1df}.photo img{width:100%;height:100%;object-fit:cover}button,a{cursor:pointer;font:inherit}label{display:flex;gap:8px;align-items:center;padding:12px}input{appearance:none;width:24px;height:24px;border:2px solid #39686a;border-radius:50%;flex:none}input:checked{background:#1b696d}input:checked:after{content:'✓';color:white;display:block;text-align:center;line-height:20px}footer{position:fixed;bottom:0;left:0;right:0;padding:16px;display:flex;justify-content:center;gap:12px;background:#f1f7f6ee;backdrop-filter:blur(12px)}footer button{border:0;border-radius:28px;padding:16px 24px;color:#fff;background:#1b696d}footer button:first-child{background:#d5e8e6;color:#164d50}dialog{border:0;padding:0;inset:0;margin:0;overflow:hidden;width:100vw;max-width:none;height:100dvh;max-height:none;background:#111e;color:white}dialog::backdrop{background:#000a}dialog[open]{display:flex;flex-direction:column}.preview{display:block;flex:1;min-height:0;width:100%;height:0;object-fit:contain}.controls{display:flex;flex:none;align-items:center;justify-content:space-between;padding:16px;padding-bottom:max(16px,env(safe-area-inset-bottom))}.controls button{background:none;color:white;border:0;font-size:28px;min-width:48px;min-height:48px}img{animation:appear .2s} @keyframes appear{from{opacity:0}to{opacity:1}}</style>
<header><span>KIGTTS · 面对面返图</span>${avatar}<h1>${name}</h1><p>${bio}</p>${contacts}<p>选择喜欢的照片，保存到你的设备。</p></header><main>${files}</main>
<footer><button id="all">全选 / 取消全选</button><button id="download">保存所选</button></footer><dialog id="viewer"><img class="preview" id="large" alt="照片预览"><div class="controls"><button id="previous" aria-label="上一张">‹</button><label><input id="check" type="checkbox">选择照片</label><button id="next" aria-label="下一张">›</button><button id="close" aria-label="关闭">×</button></div></dialog>
<script>const boxes=[...document.querySelectorAll('article input')],photos=[...document.querySelectorAll('[data-photo]')],viewer=document.getElementById('viewer');let index=0;function show(n){index=Math.max(0,Math.min(photos.length-1,n));document.getElementById('large').src='${path}file/'+boxes[index].value;document.getElementById('check').checked=boxes[index].checked;}photos.forEach((p,n)=>p.onclick=()=>{show(n);viewer.showModal()});document.getElementById('close').onclick=()=>viewer.close();document.getElementById('previous').onclick=()=>show(index-1);document.getElementById('next').onclick=()=>show(index+1);document.getElementById('check').onchange=e=>boxes[index].checked=e.target.checked;document.getElementById('all').onclick=()=>{const v=!boxes.every(b=>b.checked);boxes.forEach(b=>b.checked=v)};document.getElementById('download').onclick=()=>{const ids=boxes.filter(b=>b.checked).map(b=>b.value);if(ids.length)location.href='${path}download?ids='+ids.join(',')};let start=0;document.getElementById('large').ontouchstart=e=>start=e.changedTouches[0].clientX;document.getElementById('large').ontouchend=e=>{const d=e.changedTouches[0].clientX-start;if(Math.abs(d)>48)show(index+(d<0?1:-1))};</script></html>"""
}
